import{_ as r}from"./chunks/introduction.BIPXU4xO.js";import{_ as i,o as a,c as o,a5 as e}from"./chunks/framework.CcrBcQWS.js";const u=JSON.parse('{"title":"3. GUI 소개","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/common/gui-introduction.md","filePath":"ko/guides/common/gui-introduction.md","lastUpdated":1787021357000}'),n={name:"ko/guides/common/gui-introduction.md"};function s(d,t,l,g,c,h){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="_3-gui-소개" tabindex="-1">3. GUI 소개 <a class="header-anchor" href="#_3-gui-소개" aria-label="Permalink to &quot;3. GUI 소개&quot;">​</a></h1><p><strong>목표:</strong> 동작 명령을 전송하기 전 RBQGUI의 화면 구성과 주요 버튼을 익힙니다.</p><p><strong>사전 조건:</strong> <a href="/RBQ/nightly/ko/guides/common/controller-wifi-connect.html">컨트롤러 &amp; Wi-Fi 연결</a>이 완료되어 RBQGUI가 로봇과 연결되어 있어야 합니다.</p><h2 id="메인-화면" tabindex="-1">메인 화면 <a class="header-anchor" href="#메인-화면" aria-label="Permalink to &quot;메인 화면&quot;">​</a></h2><p>Auto Start가 완료되면 RBQGUI 메인 화면은 아래와 같이 구성됩니다:</p><figure style="margin-top:0;text-align:center;"><img src="'+r+'" alt="RBQGUI 메인 화면" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;">&lt;RBQGUI 메인 화면&gt;</figcaption></figure><p>RBQGUI는 세 가지 핵심 기능을 제공합니다:</p><ul><li><strong>연결</strong> — 로봇과 동일한 Wi-Fi 네트워크를 통해 통신합니다.</li><li><strong>제어</strong> — 보행 모드(Sit, Stance, Walk, Stair, Docking, RL)를 선택하고 조이스틱으로 로봇을 조작합니다.</li><li><strong>모니터링</strong> — 배터리, 센서, 연결 상태를 화면에서 확인합니다.</li></ul><h2 id="버튼-설명-1-9" tabindex="-1">버튼 설명 (1~9) <a class="header-anchor" href="#버튼-설명-1-9" aria-label="Permalink to &quot;버튼 설명 (1~9)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">번호</th><th>기능</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><strong>Sit</strong> — 로봇을 앉은 자세로 전환</td></tr><tr><td style="text-align:right;">2</td><td><strong>Stance</strong> — 일어나서 기본 자세로 전환</td></tr><tr><td style="text-align:right;">3</td><td><strong>Walk</strong> — 보행 (전진/후진, 좌/우 이동 및 회전)</td></tr><tr><td style="text-align:right;">4</td><td><strong>Stair</strong> — 계단 조건에 맞춘 보행 동작</td></tr><tr><td style="text-align:right;">5</td><td><strong>Docking</strong> — 충전 스테이션 정렬 및 도킹</td></tr><tr><td style="text-align:right;">6</td><td><strong>RL (Vision Trot)</strong> — 비전 기반 강화학습 보행</td></tr><tr><td style="text-align:right;">7</td><td><strong>Walking Parameter Setting</strong> — 보행 파라미터(속도/몸체 높이/발 높이) 조정</td></tr><tr><td style="text-align:right;">8</td><td><strong>3D Virtual View</strong> — 3D 가상 뷰로 전환</td></tr><tr><td style="text-align:right;">9</td><td><strong>Camera View</strong> — 카메라(실영상) 화면으로 전환</td></tr></tbody></table><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>로봇 자세가 변경되거나 앱 화면이 전환되면 해당 버튼이 주황색으로 바뀝니다.</p></div></div><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>각 버튼의 기능을 파악했다면 기본 동작 명령을 직접 시도해 보세요:</p><p><strong><a href="/RBQ/nightly/ko/guides/common/basic-motion-command.html">→ 4. 기본 동작 명령</a></strong></p>',14)])])}const _=i(n,[["render",s]]);export{u as __pageData,_ as default};
